// Small radii catch the room light along manufactured edges. The reading and
// image planes remain flat, so the archive keeps its original proportions.
function roundedPlate(width, height, depth, radius, material, parent, name) {
  const x = -width / 2, y = -height / 2;
  const shape = new THREE.Shape();
  shape.moveTo(x + radius, y);
  shape.lineTo(x + width - radius, y);
  shape.quadraticCurveTo(x + width, y, x + width, y + radius);
  shape.lineTo(x + width, y + height - radius);
  shape.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
  shape.lineTo(x + radius, y + height);
  shape.quadraticCurveTo(x, y + height, x, y + height - radius);
  shape.lineTo(x, y + radius);
  shape.quadraticCurveTo(x, y, x + radius, y);
  const bevel = Math.min(.009, depth / 5);
  const geometry = new THREE.ExtrudeGeometry(shape, { depth: depth - bevel * 2, steps: 1, bevelEnabled: true, bevelSegments: 2, bevelSize: bevel, bevelThickness: bevel, curveSegments: 5 });
  geometry.translate(0, 0, -depth / 2 + bevel);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = name; mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh);
  return mesh;
}

function rodBetween(start, end, radius, material, parent, name) {
  const a = new THREE.Vector3(...start), b = new THREE.Vector3(...end), direction = b.clone().sub(a);
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, direction.length(), 16), material);
  mesh.position.copy(a).add(b).multiplyScalar(.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize());
  mesh.name = name; mesh.castShadow = true; parent.add(mesh);
  return mesh;
}

function axialCylinder(radius, height, material, y, parent, name) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, height, 64), material);
  mesh.position.y = y; mesh.name = name; mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh);
  return mesh;
}

// A bound visitor book opens around its actual spine. The desk, page block and
